-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH base_events AS ( SELECT mri_session_id, event_name, -- Capture event_value only for the tuple count event to use as a dimension MAX(CASE WHEN event_name = 'no_of_tuples' THEN CAST(event_value AS INT) END) OVER (PARTITION BY mri_session_id) as tuple_count_val, -- Create flags for each event MAX(CASE WHEN event_name = 'Student_Deal_section' AND event_value IN ('clicked', 'loaded') THEN 1 ELSE 0 END) OVER (PARTITION BY mri_session_id) as Student_Deal_section, MAX(CASE WHEN event_name = 'student_card' AND event_value IN ('clicked', 'viewed') THEN 1 ELSE 0 END) OVER (PARTITION BY mri_session_id) as student_card, MAX(CASE WHEN event_name = 'student_details_shown' AND event_value IN ('Veiwed', 'copy link_viewed') THEN 1 ELSE 0 END) OVER (PARTITION BY mri_session_id) as student_details_shown -- ... add other MAX(CASE) flags here as needed FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-04-30 18:30:00' AND __time < TIMESTAMP '2026-05-15 18:30:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_name IN ('Student_Deal_section', 'no_of_tuples', 'student_card', 'student_details_shown') ), session_level AS ( SELECT mri_session_id, tuple_count_val, MAX(Student_Deal_section) as Student_Deal_section, MAX(student_card) as student_card, MAX(student_details_shown) as student_details_shown FROM base_events GROUP BY 1, 2 ) SELECT -- CASE -- WHEN tuple_count_val IS NULL THEN 'No Tuple Event' -- WHEN tuple_count_val <= 6 THEN CAST(tuple_count_val AS VARCHAR) -- WHEN tuple_count_val <= 10 THEN '7 to 10' -- WHEN tuple_count_val <= 20 THEN '11 to 20' -- ELSE '20 +' -- END AS tuple_range, 'Overall' tuple_range, COUNT(DISTINCT mri_session_id) as total_sessions, COUNT(DISTINCT CASE WHEN Student_Deal_section = 1 THEN mri_session_id END) AS SRP_Student_Deal_section, COUNT(DISTINCT CASE WHEN student_card = 1 THEN mri_session_id END) AS SL_student_card, COUNT(DISTINCT CASE WHEN student_details_shown = 1 THEN mri_session_id END) AS confirm_student_details_shown FROM session_level GROUP BY 1 ORDER BY 1
